import {
    BooleanColumn,
    IntegerColumn,
    ScriptColumn,
    StringColumn,
    TableNameColumn,
    Table,
    ReferenceColumn,
    DomainIdColumn,
    DomainPathColumn,
} from '../../db'

export const sys_script = Table({
    name: 'sys_script',
    schema: {
        name: StringColumn({ mandatory: true }),
        order: IntegerColumn({ default: 100, mandatory: false }),
        collection: TableNameColumn({ mandatory: true }),
        active: BooleanColumn({ read_only: true, default: true, mandatory: false }),
        when: StringColumn({
            choices: {
                before: 'before',
                after: 'after',
                async_always: 'async_always',
                before_display: 'before_display',
                async: 'async', // deprecated in Rome, but here for backwards compatibility
            },
        }),
        action_insert: BooleanColumn({}),
        action_update: BooleanColumn({}),
        action_delete: BooleanColumn({}),
        action_query: BooleanColumn({}),
        script: ScriptColumn({}),
        add_message: BooleanColumn({}),
        message: StringColumn({ mandatory: false }),
        role_conditions: StringColumn({ mandatory: false }),
        condition: StringColumn({ mandatory: false }),
        filter_condition: StringColumn({ mandatory: false }),
        template: StringColumn({ mandatory: false }),
        abort_action: BooleanColumn({ mandatory: false }),
        priority: IntegerColumn({ mandatory: false }),
        is_rest: BooleanColumn({ mandatory: false }),
        change_fields: BooleanColumn({ mandatory: false }),
        execute_function: BooleanColumn({ mandatory: false }),
        client_callable: BooleanColumn({ mandatory: false }),
        access: StringColumn({
            mandatory: false,
            choices: {
                package_private: 'package_private',
                public: 'public',
            },
        }),
        description: StringColumn({ mandatory: false }),
        advanced: BooleanColumn({ mandatory: false }),
        rest_variables: StringColumn({ mandatory: false }),
        rest_method: ReferenceColumn({ mandatory: false, referenceTable: 'sys_rest_message_fn' }),
        rest_method_text: StringColumn({ mandatory: false }),
        rest_service: ReferenceColumn({ mandatory: false, referenceTable: 'sys_rest_message' }),
        rest_service_text: StringColumn({ mandatory: false }),
        sys_domain: DomainIdColumn({ mandatory: false }),
        sys_domain_path: DomainPathColumn({ mandatory: false }),
        sys_overrides: ReferenceColumn({ mandatory: false, referenceTable: 'sys_script' }),
    },
})
